import numpy as np


def mse(pred, target):
    return np.mean((pred - target) ** 2)


def mae(pred, target):
    return np.mean(np.abs(pred - target))


def binary_cross_entropy(p, y):
    p = np.clip(p, 1e-7, 1 - 1e-7)
    return -np.mean(y * np.log(p) + (1 - y) * np.log(1 - p))


def cross_entropy(logits, target_index):
    shifted = logits - np.max(logits)
    log_probs = shifted - np.log(np.sum(np.exp(shifted)))
    return -log_probs[target_index]


def asymmetric_mse(pred, target, under_weight=3.0):
    weights = np.where(pred < target, under_weight, 1.0)
    return np.mean(weights * (pred - target) ** 2)


def show(label, value):
    print(label, None if value is None else np.round(value, 4))


pred, target = np.array([2.5, 0.0, 2.0]), np.array([3.0, -0.5, 2.0])
show("MSE:", mse(pred, target))
show("MAE:", mae(pred, target))
show("BCE:", binary_cross_entropy(np.array([0.9, 0.2]), np.array([1.0, 0.0])))
show("Cross-entropy:", cross_entropy(np.array([2.0, 1.0, 0.1]), 0))
show("Asymmetric (under-predicts):", asymmetric_mse(np.array([1.0]), np.array([2.0])))
show("Asymmetric (over-predicts):", asymmetric_mse(np.array([3.0]), np.array([2.0])))
